#[tokio::test]
async fn header_limit_from_server_builder() {
    let (io, mut peer) = mock::new();
    let peer = async move {
        peer.assert_server_handshake_with_settings(|settings: &h2::frame::Settings| {
            assert_eq!(settings.max_header_list_size(), Some(167));
        }).await;
        peer.send_frame(frames::headers(1).request("GET", "https://x/").eos()).await;
        peer
    };
    let server = async move {
        let mut conn = server::Builder::new().max_header_list_size(167).handshake::<_, Bytes>(io).await.unwrap();
        // Allow server to read the request and queue either acceptance or a 431 response.
        let result = futures::future::poll_fn(|cx| {
            match conn.poll_accept(cx) {
                std::task::Poll::Ready(value) => std::task::Poll::Ready(value),
                std::task::Poll::Pending => std::task::Poll::Ready(None),
            }
        }).await;
        assert!(result.is_some(), "request at the advertised limit was not accepted");
        (conn, result)
    };
    let _ = join(peer, server).await;
}
